package com.marketplace.productservice;
import org.springframework.cache.annotation.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class ProductService { private final ProductRepository repo;private final StockReservationRepository reservations;private final ProductMapper mapper; ProductService(ProductRepository r,StockReservationRepository sr,ProductMapper m){repo=r;reservations=sr;mapper=m;} @Transactional(readOnly=true) @Cacheable(value="products",key="#query+'-'+#pageable.pageNumber+'-'+#pageable.pageSize+'-'+#pageable.sort") public Page<ProductDtos.Response> search(String query,Pageable pageable){return (query==null||query.isBlank()?repo.findAll(pageable):repo.findByNameContainingIgnoreCase(query,pageable)).map(mapper::toResponse);}@Transactional(readOnly=true) @Cacheable(value="product",key="#id") public ProductDtos.Response get(Long id){return mapper.toResponse(repo.findById(id).orElseThrow(()->new IllegalArgumentException("Produto não encontrado")));}@CacheEvict(value={"product","products"},allEntries=true) public ProductDtos.Response create(ProductDtos.Request r){return mapper.toResponse(repo.save(new Product(r.name(),r.price(),r.stock())));}@CacheEvict(value={"product","products"},allEntries=true) public ProductDtos.Response update(Long id,ProductDtos.Request r){var p=repo.findById(id).orElseThrow();p.update(r.name(),r.price(),r.stock());return mapper.toResponse(p);}@CacheEvict(value={"product","products"},allEntries=true) public ProductDtos.Response reserve(Long id,ProductDtos.ReservationRequest r,String key){var existing=reservations.findByIdempotencyKey(key);if(existing.isPresent())return get(id);var p=repo.findByIdForUpdate(id).orElseThrow();p.reserve(r.quantity());reservations.save(new StockReservation(key,id,r.quantity()));return mapper.toResponse(p);} }
